draw:
var rate = p.rate, v = p.speed;
var F = rate * v;
var Pmotor = rate * v * v;
var Pke = 0.5 * rate * v * v;

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.lineWidth = 1.5;

var beltY = H * 0.62;
var x0 = W * 0.12, x1 = W * 0.88;
var r = 13;

// belt loop
ctx.strokeStyle = C.rule;
ctx.beginPath(); ctx.moveTo(x0, beltY - r); ctx.lineTo(x1, beltY - r); ctx.stroke();
ctx.beginPath(); ctx.moveTo(x0, beltY + r); ctx.lineTo(x1, beltY + r); ctx.stroke();
ctx.beginPath(); ctx.arc(x0, beltY, r, Math.PI / 2, 3 * Math.PI / 2); ctx.stroke();
ctx.beginPath(); ctx.arc(x1, beltY, r, -Math.PI / 2, Math.PI / 2); ctx.stroke();

// grain falling from a hopper, animated
var dropX = W * 0.34;
ctx.strokeStyle = C.faint;
ctx.beginPath();
ctx.moveTo(dropX - 22, 8); ctx.lineTo(dropX - 7, 40);
ctx.lineTo(dropX + 7, 40); ctx.lineTo(dropX + 22, 8);
ctx.stroke();
ctx.fillStyle = C.figure;
for (var k = 0; k < 6; k++) {
  var ph = ((t * 1.4 + k / 6) % 1);
  var gy = 40 + ph * (beltY - r - 40);
  var gx = dropX + ((k % 3) - 1) * 4;
  ctx.beginPath(); ctx.arc(gx, gy, 3, 0, Math.PI * 2); ctx.fill();
}

// grain already on the belt, carried right
for (var q = 0; q < 7; q++) {
  var xg = dropX + ((t * v * 9 + q * 26) % (x1 - dropX - 6));
  ctx.beginPath(); ctx.arc(xg, beltY - r - 3, 3, 0, Math.PI * 2); ctx.fill();
}

function arr(x0a, y0a, dx, dy, col) {
  ctx.strokeStyle = col; ctx.fillStyle = col;
  ctx.beginPath(); ctx.moveTo(x0a, y0a); ctx.lineTo(x0a + dx, y0a + dy); ctx.stroke();
  var L = Math.sqrt(dx * dx + dy * dy);
  var hx = dx / L, hy = dy / L;
  ctx.beginPath();
  ctx.moveTo(x0a + dx, y0a + dy);
  ctx.lineTo(x0a + dx - 7 * hx + 4 * hy, y0a + dy - 7 * hy - 4 * hx);
  ctx.lineTo(x0a + dx - 7 * hx - 4 * hy, y0a + dy - 7 * hy + 4 * hx);
  ctx.closePath(); ctx.fill();
}

// belt velocity and motor force
arr(x1 - 90, beltY + r + 22, 60, 0, C.faint);
ctx.fillStyle = C.faint;
ctx.fillText("belt v = " + v.toFixed(1) + " m/s", x1 - 150, beltY + r + 26);

arr(dropX + 10, beltY - r - 14, 52, 0, C.accent);
ctx.fillStyle = C.accent;
ctx.fillText("F = (dm/dt) v = " + F.toFixed(1) + " N", dropX + 16, beltY - r - 22);

ctx.fillStyle = C.ink;
ctx.fillText("grain in at " + rate.toFixed(1) + " kg/s", dropX - 40, 54);
ctx.fillText("motor P = (dm/dt) v^2", 10, H - 22);
ctx.fillStyle = C.faint;
ctx.fillText("half becomes kinetic energy, half is rubbed away as heat", 10, H - 6);

out.note = "motor supplies " + Pmotor.toFixed(1) + " W; grain gains KE at "
  + Pke.toFixed(1) + " W; friction wastes " + (Pmotor - Pke).toFixed(1) + " W";
